import re
import os


def task_func(request):
    if not isinstance(request, str):
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    match = re.match(r"^GET\s+(/\S*)\s+HTTP/\d(?:\.\d)?(?:\r?\n|$)", request)
    if not match:
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    filename = match.group(1).split("?", 1)[0].lstrip("/")
    base_directory = os.path.abspath(os.getcwd())
    file_path = os.path.abspath(os.path.join(base_directory, filename))

    if not file_path.startswith(base_directory + os.sep):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    if not os.path.isfile(file_path):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            content = file.read()
    except (OSError, UnicodeDecodeError):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    return (
        "HTTP/1.1 200 OK\r\n"
        f"Content-Length: {len(content.encode('utf-8'))}\r\n"
        "\r\n"
        f"{content}"
    )

