# Constants
MIN_PERCENTAGE = 0.75


def task_func(data, cols, percentage):
    """Find column pairs with absolute correlation above the given threshold."""
    threshold = max(float(percentage), MIN_PERCENTAGE)
    corr_combinations = []

    for column_a, column_b in combinations(cols, 2):
        correlation = data[column_a].corr(data[column_b])
        if pd.notna(correlation) and abs(correlation) > threshold:
            corr_combinations.append((column_a, column_b))

    return {"corr_combinations": corr_combinations}

import re
import os
import subprocess


def task_func(dir_path, exe_pattern, execute_files=True):
    pattern = re.compile(exe_pattern)
    results = []

    try:
        entries = sorted(os.scandir(dir_path), key=lambda entry: entry.name)
    except (OSError, TypeError):
        return results

    for entry in entries:
        if not entry.is_file():
            continue
        if not pattern.search(entry.name):
            continue
        if not os.access(entry.path, os.X_OK):
            continue

        file_path = os.path.abspath(entry.path)

        if execute_files:
            try:
                completed = subprocess.run(
                    [file_path],
                    capture_output=True,
                    text=True,
                    check=False,
                )
                results.append(completed.stdout)
            except (OSError, subprocess.SubprocessError):
                continue
        else:
            results.append(file_path)

    return results

