import numpy as np
import pandas as pd
from sklearn.preprocessing import StandardScaler


def task_func(P, T):
    P = np.asarray(P)
    T = np.asarray(T)

    if P.ndim != 2 or T.ndim != 3:
        raise ValueError("P must be 2D and T must be 3D.")

    if P.shape[1] != T.shape[0]:
        raise ValueError(
            "The number of columns in P must match the first dimension of T."
        )

    result = np.tensordot(P, T, axes=([1], [0]))
    flattened_result = result.reshape(result.shape[0], -1)
    normalized_result = StandardScaler().fit_transform(flattened_result)

    columns = [
        f"feature_{index}" for index in range(normalized_result.shape[1])
    ]
    return pd.DataFrame(normalized_result, columns=columns)

