def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    products = ["Apple", "Banana", "Orange", "Pear", "Grape"]
    rng = random.Random(seed)
    product_by_code = {}
    rows = []

    for segment in s.splitlines():
        segment = segment.strip()
        if not segment:
            continue

        parts = re.split(r"\s+", segment, maxsplit=4)
        if len(parts) != 5:
            raise ValueError("Each segment must contain ID, quantity, code, price, and description")

        item_id, quantity, code, price, description = (
            part.rstrip() for part in parts
        )

        if code not in product_by_code:
            product_by_code[code] = rng.choice(products)

        rows.append(
            {
                "ID": int(item_id),
                "Quantity": int(quantity),
                "Code": code,
                "Price": int(price),
                "Product": product_by_code[code],
                "Description": description,
            }
        )

    return pd.DataFrame(
        rows,
        columns=["ID", "Quantity", "Code", "Price", "Product", "Description"],
    )

import itertools
import math
from pandas import Series


def task_func(elements, subset_size, top_n=2):
    if subset_size == 0 or subset_size > len(elements):
        return 1

    subset_sums = [
        sum(subset)
        for subset in itertools.combinations(elements, subset_size)
    ]

    product_of_sums = math.prod(subset_sums)
    top_sums = sorted(subset_sums, reverse=True)[:top_n]

    return product_of_sums, Series(top_sums)

import subprocess
import os
import signal
import time


def task_func(process_name: str) -> int:
    if not process_name:
        return 0

    current_pid = os.getpid()
    processes = []

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/FO", "CSV", "/NH"],
                capture_output=True,
                text=True,
                check=False,
            )
            for line in result.stdout.splitlines():
                fields = [field.strip('"') for field in line.split('","')]
                if len(fields) >= 2 and fields[0] == process_name:
                    try:
                        processes.append(int(fields[1]))
                    except ValueError:
                        continue
        else:
            result = subprocess.run(
                ["ps", "-eo", "pid=,comm="],
                capture_output=True,
                text=True,
                check=False,
            )
            for line in result.stdout.splitlines():
                parts = line.strip().split(None, 1)
                if len(parts) == 2 and parts[1] == process_name:
                    try:
                        pid = int(parts[0])
                    except ValueError:
                        continue
                    if pid != current_pid:
                        processes.append(pid)
    except (OSError, subprocess.SubprocessError):
        return 0

    stopped = 0
    for pid in processes:
        try:
            os.kill(pid, signal.SIGTERM)
            stopped += 1
        except (ProcessLookupError, PermissionError, OSError):
            continue

    if stopped:
        time.sleep(1)

    return stopped

