import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    os.makedirs(BACKUP_DIR, exist_ok=True)
    index = 0

    while True:
        suffix = '' if index == 0 else f'_{index}'
        backup_path = os.path.join(BACKUP_DIR, f'backup{suffix}')

        if not os.path.exists(backup_path):
            return backup_path

        index += 1


def task_func(directory):
    errors = []

    try:
        backup_directory = get_unique_backup_dir()
        os.makedirs(backup_directory)
    except Exception as error:
        return "", [str(error)]

    if not os.path.isdir(directory):
        return backup_directory, [f"Directory does not exist: {directory}"]

    try:
        entries = os.listdir(directory)
    except Exception as error:
        return backup_directory, [str(error)]

    for entry in entries:
        source = os.path.join(directory, entry)
        destination = os.path.join(backup_directory, entry)

        try:
            if os.path.isdir(source) and not os.path.islink(source):
                shutil.copytree(source, destination)
            else:
                shutil.copy2(source, destination)
        except Exception as error:
            errors.append(f"Backup failed for '{source}': {error}")
            continue

        try:
            if os.path.isdir(source) and not os.path.islink(source):
                shutil.rmtree(source)
            else:
                os.remove(source)
        except Exception as error:
            errors.append(f"Cleanup failed for '{source}': {error}")

    return backup_directory, errors

import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    failed_files = []

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except OSError:
        return {
            "success": False,
            "message": "Could not create the destination folder.",
            "failed_files": [],
        }

    source_files = [
        path for path in glob(os.path.join(src_folder, "*"))
        if os.path.isfile(path)
    ]

    processes = []

    for source_path in source_files:
        compressed_path = source_path + ".gz"
        try:
            process = subprocess.Popen(
                ["gzip", "-c", source_path],
                stdout=open(compressed_path, "wb"),
                stderr=subprocess.PIPE,
            )
            processes.append((process, source_path, compressed_path))
        except (OSError, IOError):
            failed_files.append(os.path.basename(source_path))

    for process, source_path, compressed_path in processes:
        try:
            _, stderr = process.communicate()

            if process.returncode != 0:
                failed_files.append(os.path.basename(source_path))
                if os.path.exists(compressed_path):
                    os.remove(compressed_path)
                continue

            destination_path = os.path.join(
                dst_folder, os.path.basename(compressed_path)
            )
            shutil.move(compressed_path, destination_path)
        except (OSError, IOError):
            failed_files.append(os.path.basename(source_path))
            if os.path.exists(compressed_path):
                try:
                    os.remove(compressed_path)
                except OSError:
                    pass

    success = not failed_files
    return {
        "success": success,
        "message": (
            "All files were compressed and moved successfully."
            if success
            else "Some files could not be compressed or moved."
        ),
        "failed_files": failed_files,
    }

