def task_func(data_list, seed=0):
    rng = random.Random(seed)
    modified_strings = []

    for value in data_list:
        parts = value.split(",")
        candidates = [i for i, part in enumerate(parts) if part]

        if candidates:
            index = rng.choice(candidates)
            parts[index] = "".join(
                rng.choices(string.ascii_lowercase, k=len(parts[index]))
            )

        modified_strings.append(",".join(parts))

    return pd.DataFrame(
        {
            "Original String": data_list,
            "Modified String": modified_strings,
        }
    )

