import string
import random

def task_func(text, seed=None):
    if not text:
        raise ValueError("Input text cannot be empty")

    rng = random.Random(seed)
    result = []

    for char in text:
        if char in string.ascii_letters:
            result.append(rng.choice(string.ascii_lowercase))
        elif char in string.digits:
            result.append(rng.choice(string.digits))
        elif char == " ":
            character_set = rng.choice(
                (string.digits, string.ascii_lowercase)
            )
            result.append(rng.choice(character_set))
        else:
            result.append(char)

    return "".join(result)

import re
import json
from collections import Counter

def task_func(json_str, top_n=10):
    data = json.loads(json_str)
    url_pattern = re.compile(r"https?://[^\s\"'<>]+")

    def collect_strings(value):
        if isinstance(value, dict):
            for key, item in value.items():
                yield from collect_strings(key)
                yield from collect_strings(item)
        elif isinstance(value, list):
            for item in value:
                yield from collect_strings(item)
        elif isinstance(value, str):
            yield value

    urls = []
    for text in collect_strings(data):
        for match in url_pattern.findall(text):
            urls.append(match.rstrip(".,;:!?)]}"))

    return dict(Counter(urls).most_common(top_n))

