import json
import re
import pandas as pd


def task_func(json_str):
    if not json_str or not isinstance(json_str, str):
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    number_pattern = re.compile(
        r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$"
    )

    def normalize(value):
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return float(value * 2)
        if isinstance(value, list):
            return [normalize(item) for item in value]
        if isinstance(value, str):
            stripped = value.strip()
            if number_pattern.fullmatch(stripped):
                return float(stripped) * 2
        return value

    normalized = {key: normalize(value) for key, value in data.items()}

    try:
        list_lengths = [
            len(value) for value in normalized.values() if isinstance(value, list)
        ]

        if not list_lengths:
            return pd.DataFrame([normalized])

        row_count = max(list_lengths)
        rows = {}

        for key, value in normalized.items():
            if isinstance(value, list):
                rows[key] = value + [None] * (row_count - len(value))
            else:
                rows[key] = [value] * row_count

        return pd.DataFrame(rows)
    except (TypeError, ValueError):
        return pd.DataFrame()

