import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    start_time = time.time()
    records = []

    while time.time() - start_time < duration:
        if platform.system() == "Windows":
            command = "wmic cpu get loadpercentage"
        else:
            command = "top -bn1 | grep 'Cpu(s)'"

        output = subprocess.check_output(command, shell=True)
        if isinstance(output, bytes):
            output = output.decode("utf-8", errors="ignore")

        cpu_usage = None
        lines = [line.strip() for line in output.splitlines() if line.strip()]

        if platform.system() == "Windows":
            for line in lines:
                try:
                    cpu_usage = float(line)
                    break
                except ValueError:
                    continue
        else:
            for line in lines:
                parts = line.replace(",", " ").split()
                for index, part in enumerate(parts[:-1]):
                    if part.lower() == "id":
                        try:
                            cpu_usage = 100.0 - float(parts[index - 1])
                        except (ValueError, IndexError):
                            pass
                        break
                if cpu_usage is not None:
                    break

            if cpu_usage is None:
                for part in parts:
                    try:
                        cpu_usage = float(part)
                        break
                    except ValueError:
                        continue

        if cpu_usage is None:
            cpu_usage = 0.0

        records.append(
            {
                "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
                "cpu_usage": cpu_usage,
            }
        )

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as logfile:
            json.dump(records, logfile, indent=4)
    except IOError:
        return None

    return LOGFILE_PATH

