    future_indices = np.arange(n_samples, 2 * n_samples).reshape(-1, 1)
    return np.asarray(model.predict(future_indices), dtype=float)

import re
import glob
from docx import Document


def task_func(directory_path: str) -> int:
    docx_files = glob.glob(f"{directory_path}/*.docx")

    def protect_paragraph(paragraph):
        for run in paragraph.runs:
            run.text = re.sub(r'"', r'\\"', run.text)

    def protect_table(table):
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    protect_paragraph(paragraph)
                for nested_table in cell.tables:
                    protect_table(nested_table)

    for file_path in docx_files:
        document = Document(file_path)

        for paragraph in document.paragraphs:
            protect_paragraph(paragraph)

        for table in document.tables:
            protect_table(table)

        for section in document.sections:
            for paragraph in section.header.paragraphs:
                protect_paragraph(paragraph)
            for paragraph in section.footer.paragraphs:
                protect_paragraph(paragraph)

        document.save(file_path)

    return len(docx_files)

