import re
import json
import requests


def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        data = json.loads(response.text)
        text = json.dumps(data)

        pattern = re.compile(
            r'"name"\s*:\s*("(?:\\.|[^"\\])*")'
        )

        def bracket_depth(position: int) -> int:
            depth = 0
            in_string = False
            escaped = False

            for char in text[:position]:
                if in_string:
                    if escaped:
                        escaped = False
                    elif char == "\\":
                        escaped = True
                    elif char == '"':
                        in_string = False
                elif char == '"':
                    in_string = True
                elif char == "[":
                    depth += 1
                elif char == "]":
                    depth -= 1

            return depth

        return [
            json.loads(match.group(1))
            for match in pattern.finditer(text)
            if bracket_depth(match.start()) == 0
        ]
    except Exception:
        return "Invalid url input"

