from typing import List, Union
import numpy as np
import scipy.fft
from collections import Counter


def task_func(data: List[Union[int, str]], repetitions: int = 1):
    if not data or repetitions <= 0:
        return {
            "mode": np.array([]),
            "count": np.array([], dtype=int),
        }

    repeated_data = data * repetitions
    frequencies = Counter(repeated_data)
    maximum_count = max(frequencies.values())

    modes = [value for value, count in frequencies.items() if count == maximum_count]

    try:
        modes.sort()
    except TypeError:
        modes.sort(key=lambda value: (type(value).__name__, str(value)))

    return {
        "mode": np.array(modes),
        "count": np.full(len(modes), maximum_count, dtype=int),
    }

import numpy as np
import pandas as pd
import numbers


def task_func(
    products,
    n_samples=100,
    sales_lower=50,
    sales_upper=200,
    profit_margin_min=0.1,
    profit_margin_max=0.5,
    random_seed=42,
):
    if (
        not isinstance(products, list)
        or not all(isinstance(product, str) for product in products)
    ):
        raise TypeError("products must be a list of strings")

    if (
        not isinstance(sales_lower, numbers.Number)
        or not isinstance(sales_upper, numbers.Number)
        or not isinstance(profit_margin_min, numbers.Number)
        or not isinstance(profit_margin_max, numbers.Number)
    ):
        raise TypeError("Sales and profit margin bounds must be numeric")

    if (
        isinstance(n_samples, bool)
        or not isinstance(n_samples, (int, np.integer))
        or n_samples <= 0
    ):
        raise ValueError("n_samples must be a positive integer")

    if sales_lower > sales_upper:
        raise ValueError("sales_lower must not be greater than sales_upper")

    rng = np.random.default_rng(random_seed)

    if not products:
        return pd.DataFrame(columns=["Product", "Sales", "Profit"])

    selected_products = rng.choice(products, size=n_samples)
    sales = rng.uniform(sales_lower, sales_upper, size=n_samples)
    profit_margins = rng.uniform(
        profit_margin_min, profit_margin_max, size=n_samples
    )
    profit = sales * profit_margins

    data = pd.DataFrame(
        {
            "Product": selected_products,
            "Sales": sales,
            "Profit": profit,
        }
    )

    return (
        data.groupby("Product", as_index=False)[["Sales", "Profit"]]
        .sum()
        .sort_values("Profit", ascending=False, ignore_index=True)
    )

