import xml.etree.ElementTree as ET
import csv


def task_func(xml_content, output_csv_path):
    root = ET.fromstring(xml_content)

    records = list(root)
    if not records:
        records = [root]

    fieldnames = []
    rows = []

    for record in records:
        row = {}

        for key, value in record.attrib.items():
            row[key] = value
            if key not in fieldnames:
                fieldnames.append(key)

        for child in record:
            value = "".join(child.itertext()).strip()
            row[child.tag] = value
            if child.tag not in fieldnames:
                fieldnames.append(child.tag)

        if not record.attrib and len(record) == 0:
            row[record.tag] = (record.text or "").strip()
            if record.tag not in fieldnames:
                fieldnames.append(record.tag)

        rows.append(row)

    with open(output_csv_path, "w", newline="", encoding="utf-8") as csv_file:
        writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)

