import importlib
from pkgutil import iter_modules

def task_func(package_name):
    try:
        package = importlib.import_module(package_name)
    except ImportError as exc:
        raise ImportError(
            f"Package '{package_name}' is not installed or cannot be found. "
            f"Please install it with: pip install {package_name}"
        ) from exc

    package_paths = list(getattr(package, "__path__", []))
    if not package_paths:
        raise ImportError(
            f"'{package_name}' is not a package. "
            f"Please install it with: pip install {package_name}"
        )

    module_names = []
    for module_path in package_paths:
        if module_path not in sys.path:
            sys.path.append(module_path)

        for _, module_name, _ in iter_modules([module_path]):
            if module_name not in module_names:
                module_names.append(module_name)

    return module_names

