import subprocess
import psutil
import time
import os


def task_func(script_path: str, timeout=10) -> dict:
    result = {"CPU Usage": 0.0, "Memory Usage": 0}

    if not os.path.exists(script_path):
        return result

    process = subprocess.Popen(["bash", script_path])
    monitored_process = psutil.Process(process.pid)
    start_time = time.monotonic()

    try:
        monitored_process.cpu_percent(None)

        while process.poll() is None:
            remaining = timeout - (time.monotonic() - start_time)
            if remaining <= 0:
                break

            interval = min(0.1, remaining)
            result["CPU Usage"] += monitored_process.cpu_percent(interval=interval)

            try:
                if monitored_process.status() == psutil.STATUS_ZOMBIE:
                    break
                result["Memory Usage"] += monitored_process.memory_info().rss
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break

    finally:
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()

    return result

