import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    result = data.copy()

    acronyms = [
        acronym for acronym in mapping
        if isinstance(acronym, str) and acronym
    ]

    if not acronyms:
        return result

    pattern = re.compile(
        r"(?<!\w)(?:"
        + "|".join(re.escape(acronym) for acronym in sorted(acronyms, key=len, reverse=True))
        + r")(?!\w)"
    )

    def replace_acronyms(value):
        if isinstance(value, str):
            return pattern.sub(lambda match: mapping[match.group(0)], value)
        return value

    for column in result.columns:
        result[column] = result[column].map(replace_acronyms)

    return result

