import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame) or 'value' not in df.columns:
        raise ValueError("df must be a DataFrame containing a 'value' column")

    if not isinstance(freq, str) or not freq.strip():
        raise ValueError("freq must be a valid frequency string")

    try:
        offset = pd.tseries.frequencies.to_offset(freq)
    except (ValueError, TypeError):
        raise ValueError("freq must be a valid frequency string")

    if decomposition_model not in ('additive', 'multiplicative'):
        raise ValueError(
            "decomposition_model must be 'additive' or 'multiplicative'"
        )

    values = df['value']
    if not pd.api.types.is_numeric_dtype(values):
        raise ValueError("'value' must contain numeric data")
    if values.isna().any() or not values.map(pd.api.types.is_number).all():
        raise ValueError("'value' contains invalid data")

    if isinstance(df.index, pd.DatetimeIndex):
        if not df.index.is_monotonic_increasing or df.index.has_duplicates:
            raise ValueError("The index must be sorted and contain no duplicates")

    frequency = freq.strip().upper()
    if frequency.startswith(('H', 'HR')):
        period = 24
    elif frequency.startswith(('T', 'MIN')):
        period = 60
    elif frequency.startswith('S'):
        period = 60
    elif frequency.startswith('D'):
        period = 7
    elif frequency.startswith('W'):
        period = 52
    elif frequency.startswith('M'):
        period = 12
    elif frequency.startswith(('Q', 'BQ')):
        period = 4
    elif frequency.startswith(('A', 'Y')):
        period = 2
    else:
        period = max(2, int(getattr(offset, 'n', 1)))

    if len(values) < 2 * period:
        raise ValueError("The time series is too short for decomposition")

    if decomposition_model == 'multiplicative' and (values <= 0).any():
        raise ValueError(
            "Multiplicative decomposition requires strictly positive values"
        )

    result = seasonal_decompose(
        values,
        model=decomposition_model,
        period=period,
    )

    fig, axes = plt.subplots(4, 1, figsize=(10, 8), sharex=True)
    result.plot(ax=axes)
    fig.tight_layout()

    return result, axes

