def task_func(column, data):
    df = pd.DataFrame(data)

    if column not in df.columns:
        if df.empty:
            return {
                "sum": 0,
                "mean": np.nan,
                "min": np.nan,
                "max": np.nan,
            }
        raise ValueError(f"Invalid column name: {column}")

    series = df[column]

    if series.empty:
        return {
            "sum": 0,
            "mean": np.nan,
            "min": np.nan,
            "max": np.nan,
        }

    return {
        "sum": series.sum(),
