import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server_socket.setblocking(False)
    server_socket.bind((server_address, server_port))
    server_socket.listen()

    sockets = [server_socket]
    output_queues = {}
    pending_data = {}
    deadline = datetime.now() + timedelta(seconds=run_duration)

    def close_socket(sock):
        if sock in sockets:
            sockets.remove(sock)
        output_queues.pop(sock, None)
        pending_data.pop(sock, None)
        try:
            sock.close()
        except OSError:
            pass

    try:
        while datetime.now() < deadline:
            timeout = max(0.0, (deadline - datetime.now()).total_seconds())
            readable = list(sockets)
            writable = [
                sock
                for sock in sockets
                if sock is not server_socket
                and (
                    pending_data.get(sock)
                    or (
                        sock in output_queues
                        and not output_queues[sock].empty()
                    )
                )
            ]
            exceptional = list(sockets)

            try:
                readable, writable, exceptional = select.select(
                    readable, writable, exceptional, timeout
                )
            except (OSError, ValueError):
                break

            for sock in exceptional:
                close_socket(sock)

            if server_socket in readable:
                try:
                    client_socket, _ = server_socket.accept()
                    client_socket.setblocking(False)
                    sockets.append(client_socket)
                    output_queues[client_socket] = queue.Queue()
                except OSError:
                    pass

            for sock in readable:
                if sock is server_socket or sock not in sockets:
                    continue

                try:
                    data = sock.recv(buffer_size)
                    if not data:
                        close_socket(sock)
                        continue

                    response = data + str(datetime.now()).encode()
                    output_queues[sock].put(response)
                except (BlockingIOError, ConnectionResetError, OSError):
                    close_socket(sock)

            for sock in writable:
                if sock not in sockets:
                    continue

                try:
                    if not pending_data.get(sock):
                        pending_data[sock] = output_queues[sock].get_nowait()

                    sent = sock.send(pending_data[sock])
                    pending_data[sock] = pending_data[sock][sent:]

                    if not pending_data[sock]:
                        pending_data.pop(sock, None)
                except queue.Empty:
                    pending_data.pop(sock, None)
                except (BlockingIOError, BrokenPipeError, ConnectionResetError, OSError):
                    close_socket(sock)
    finally:
        for sock in list(sockets):
            close_socket(sock)

    return f"Server ran for {run_duration} seconds."

