              latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
              other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
              rng_seed=None):
    if start_year > end_year:
        raise ValueError("start_year must not exceed end_year")
    if start_year < 0 or end_year > 9999:
        raise ValueError("Years must be between 0 and 9999")
    if not latin_names and not other_names:
        raise ValueError("At least one name must be provided")

    def correct_encoding(name):
        corrected = str(name)
        for _ in range(2):
            try:
                candidate = corrected.encode("latin1").decode("utf-8")
            except (UnicodeEncodeError, UnicodeDecodeError):
                break
            if candidate == corrected:
                break
            corrected = candidate
        return corrected

    names = [correct_encoding(name) for name in latin_names + other_names]
    rng = np.random.RandomState(rng_seed)

    records = []
    for identifier in range(1, 101):
        name = names[rng.randint(0, len(names))]
        year = int(rng.randint(start_year, end_year + 1))
        month = int(rng.randint(1, 13))
        day = int(rng.randint(1, 29))

        if year == 0:
            date_of_birth = f"{year:04d}-{month:02d}-{day:02d} 00:00:00"
        else:
            date_of_birth = datetime.datetime(year, month, day)

        email = f"{name.lower()}{year}@{email_domain}"
        records.append(
            {
                "ID": identifier,
                "Name": name,
                "Date of Birth": date_of_birth,
                "Email": email,
            }
        )

    return pd.DataFrame(records, columns=["ID", "Name", "Date of Birth", "Email"])

