import csv
import collections


def task_func(csv_file, emp_prefix='EMP$$'):
    """Count CSV records for each employee matching the specified prefix."""
    should_close = False

    if isinstance(csv_file, (str, bytes)):
        csv_file = open(csv_file, newline='', encoding='utf-8')
        should_close = True

    try:
        reader = csv.DictReader(csv_file)
        if not reader.fieldnames:
            return {}

        employee_field = next(
            (
                field for field in reader.fieldnames
                if field.strip().lower() in {
                    'employee', 'employee_id', 'employee id',
                    'emp_id', 'emp id'
                }
            ),
            reader.fieldnames[0]
        )

        counts = collections.Counter()

        for row in reader:
            employee = row.get(employee_field)
            if employee is not None:
                employee = employee.strip()
                if employee.startswith(emp_prefix):
                    counts[employee] += 1

        return dict(counts)
    finally:
        if should_close:
            csv_file.close()

import re
import nltk
from string import punctuation

def task_func(df):
    if df.empty or not {"Title", "Content"}.issubset(df.columns):
        raise ValueError(
            "The DataFrame must be non-empty and contain 'Title' and 'Content' columns."
        )

    matched = df["Title"].fillna("").astype(str).str.contains(
        r"like|what", case=False, na=False, regex=True
    )

    translation = str.maketrans({char: " " for char in punctuation})
    frequencies = {}

    for content in df.loc[matched, "Content"].fillna(""):
        cleaned = str(content).translate(translation).casefold()
        words = re.findall(r"[^\W_]+", cleaned, flags=re.UNICODE)

        for word in words:
            frequencies[word] = frequencies.get(word, 0) + 1

    return frequencies

