from collections import defaultdict
import numpy as np
import matplotlib.pyplot as plt


def task_func(data):
    if not isinstance(data, list):
        raise TypeError("Input data must be a list of dictionaries.")
    if not data:
        raise ValueError("Input data cannot be empty.")
    if not all(isinstance(item, dict) for item in data):
        raise TypeError("Input data must be a list of dictionaries.")

    grouped_values = defaultdict(list)

    for item in data:
        for key, value in item.items():
            if isinstance(value, bool) or not isinstance(
                value, (int, float, np.number)
            ):
                raise TypeError("All dictionary values must be numeric.")
            if np.iscomplexobj(value):
                raise TypeError("All dictionary values must be real numeric values.")
            grouped_values[key].append(value)

    statistics = {}
    axes = []

    for key, values in grouped_values.items():
        mean = float(np.mean(values))
        standard_deviation = float(np.std(values))

        statistics[key] = {
            "mean": mean,
            "std": standard_deviation,
        }

        _, ax = plt.subplots()
        ax.bar(
            ["Mean", "Standard Deviation"],
            [mean, standard_deviation],
        )
        ax.set_title(f"Statistics for {key}")
        ax.set_ylabel("Value")
        axes.append(ax)

    return statistics, axes

import warnings
import os
import glob
import shutil
import time


def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    transferred_files = []

    try:
        os.makedirs(DEST_DIR, exist_ok=True)
    except Exception as error:
        warnings.warn(f"Could not create destination directory: {error}")
        return transferred_files

    if isinstance(EXTENSIONS, str):
        EXTENSIONS = [EXTENSIONS]

    seen_files = set()

    for extension in EXTENSIONS:
        extension = str(extension)
        pattern = f"*{extension}" if extension.startswith(".") else f"*.{extension}"

        for source_path in glob.glob(os.path.join(SOURCE_DIR, pattern)):
            if source_path in seen_files or not os.path.isfile(source_path):
                continue

            seen_files.add(source_path)

            try:
                shutil.move(source_path, os.path.join(DEST_DIR, os.path.basename(source_path)))
                transferred_files.append(os.path.basename(source_path))
            except Exception as error:
                warnings.warn(
                    f"Could not transfer file '{source_path}': {error}"
                )

    return transferred_files

import pandas as pd
from random import seed, choices

def task_func(L, num_dataframes=5, random_seed=None):
    if not L:
        return pd.DataFrame(), []

    seed(random_seed)

    column_names = choices("abcdefghijklmnopqrstuvwxyz", k=len(L[0]))
    df_list = [
        pd.DataFrame(choices(L, k=3), columns=column_names)
        for _ in range(num_dataframes)
    ]

    if not df_list:
        return pd.DataFrame(columns=column_names), []

    common = set(map(tuple, df_list[0].to_numpy()))
    for df in df_list[1:]:
        common &= set(map(tuple, df.to_numpy()))

    common_rows = [
        row for row in map(tuple, df_list[0].to_numpy()) if row in common
    ]
    common_rows = list(dict.fromkeys(common_rows))

    return pd.DataFrame(common_rows, columns=column_names), df_list

