import time
import numpy as np


def task_func(samples=10, delay=0.1):
    if samples <= 0:
        raise ValueError("samples must be greater than zero")
    if delay < 0:
        raise ValueError("delay must be non-negative")

    delay_times = []

    for _ in range(samples):
        start = time.perf_counter()
        time.sleep(delay)
        delay_times.append(time.perf_counter() - start)

    return np.mean(delay_times), np.std(delay_times)

import numpy as np
import cv2
import os
import numbers


def task_func(image_path='image.jpg', threshold=128):
    if not isinstance(threshold, numbers.Integral) or isinstance(threshold, bool):
        raise ValueError("threshold must be an integer between 0 and 255")
    if not 0 <= threshold <= 255:
        raise ValueError("threshold must be an integer between 0 and 255")

    if not os.path.isfile(image_path):
        raise FileNotFoundError(image_path)

    original_image = cv2.imread(image_path, cv2.IMREAD_GRAYSCALE)
    if original_image is None:
        raise FileNotFoundError(image_path)

    _, binary_image = cv2.threshold(
        original_image, int(threshold), 255, cv2.THRESH_BINARY
    )
    cv2.imwrite("binary_image.jpg", binary_image)

    return original_image, binary_image

import binascii
import numpy as np
import matplotlib.pyplot as plt
import pandas as pd


def task_func(hex_str):
    if not isinstance(hex_str, str):
        raise ValueError("'hex_str' must be a valid hex string")

    if hex_str.startswith("\\x"):
        hex_body = hex_str[2:]
        if "\\x" in hex_body:
            parts = hex_body.split("\\x")
            if any(len(part) != 2 for part in parts):
                raise ValueError("'hex_str' is not a valid hex string")
            hex_body = "".join(parts)
    else:
        hex_body = hex_str

    try:
        byte_data = binascii.unhexlify(hex_body)
    except (binascii.Error, ValueError, TypeError) as exc:
        raise ValueError("'hex_str' is not a valid hex string") from exc

    byte_values, frequencies = np.unique(
        np.frombuffer(byte_data, dtype=np.uint8),
        return_counts=True,
    )

    data = pd.DataFrame(
        {
            "Byte Value": byte_values,
            "Frequency": frequencies,
        }
    )

    _, ax = plt.subplots()
    ax.bar(data["Byte Value"], data["Frequency"])
    ax.set_xlabel("Byte Value")
    ax.set_ylabel("Frequency")

    return data, ax

import re
import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    if pattern == "":
        return df.copy()

    regex = re.compile(pattern)

    def reverse_matching_words(value):
        if not isinstance(value, str):
            return value

        words = value.split()
        matching_words = [word for word in words if regex.search(word)]
        matching_words.reverse()

        matching_index = 0
        result = []
        for word in words:
            if regex.search(word):
                result.append(matching_words[matching_index])
                matching_index += 1
            else:
                result.append(word)

        return " ".join(result)

    result = df.copy()
    result[column_name] = result[column_name].apply(reverse_matching_words)
    return result

