import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str}
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"
):
    if not os.path.isfile(file_path):
        raise ValueError(f"File does not exist: {file_path}")

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError(f"Unable to read valid JSON from file: {file_path}") from error

    expected_root_type = INPUT_JSON.get("type")
    if expected_root_type == "object" and not isinstance(data, dict):
        raise ValueError("JSON root must be an object")

    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])

    for name in required:
        if name not in data:
            raise ValueError(f"Missing required attribute: {name}")

    for name, schema in properties.items():
        if name in data:
            expected_type = schema.get("type")
            if expected_type is not None:
                if expected_type is int and isinstance(data[name], bool):
                    raise ValueError(f"Invalid type for attribute: {name}")
                if not isinstance(data[name], expected_type):
                    raise ValueError(f"Invalid type for attribute: {name}")

    if "email" in data and not re.fullmatch(EMAIL_REGEX, data["email"]):
        raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute not found: {attribute}")

    return data[attribute]

