import requests
from bs4 import BeautifulSoup
import pandas as pd


def task_func(url='http://example.com'):
    response = requests.get(url)
    response.raise_for_status()

    try:
        soup = BeautifulSoup(response.content, 'html.parser')
    except Exception as exc:
        raise ValueError("Page content could not be parsed") from exc

    table = soup.find('table')
    if table is None:
        raise ValueError("No table found on the page")

    headers = []
    rows = []

    for tr in table.find_all('tr'):
        header_cells = tr.find_all('th')
        data_cells = tr.find_all('td')

        if header_cells and not headers:
            headers = [cell.get_text(strip=True) for cell in header_cells]
        elif data_cells:
            rows.append([cell.get_text(strip=True) for cell in data_cells])

    if not rows:
        raise ValueError("No table data found on the page")

    try:
        return pd.DataFrame(rows, columns=headers if headers else None)
    except (ValueError, TypeError) as exc:
        raise ValueError("Table data could not be parsed") from exc

