import pandas as pd
import folium
from geopy.geocoders import Photon


def task_func(dic):
    geolocator = Photon(user_agent="geoapiExercises")
    records = []

    for name, value in dic.items():
        if isinstance(value, str):
            location = geolocator.geocode(value)
            if location is None:
                continue
            latitude, longitude = location.latitude, location.longitude
        elif isinstance(value, dict):
            if "address" in value:
                location = geolocator.geocode(value["address"])
                if location is None:
                    continue
                latitude, longitude = location.latitude, location.longitude
            else:
                latitude = value["latitude"]
                longitude = value["longitude"]
        else:
            latitude, longitude = value[0], value[1]

        records.append(
            {
                "name": name,
                "latitude": float(latitude),
                "longitude": float(longitude),
            }
        )

    locations = pd.DataFrame(
        records, columns=["name", "latitude", "longitude"]
    )

    if locations.empty:
        return folium.Map(location=[0, 0], zoom_start=2)

    center = [
        locations["latitude"].mean(),
        locations["longitude"].mean(),
    ]
    result = folium.Map(location=center, zoom_start=2)

    for row in locations.itertuples(index=False):
        folium.Marker(
            location=[row.latitude, row.longitude],
            popup=str(row.name),
        ).add_to(result)

    return result

