import matplotlib.pyplot as plt

# Constants
ROOMS = ["Room1", "Room2", "Room3", "Room4", "Room5"]


def task_func(date_str, booking_data):
    if not isinstance(date_str, str):
        raise ValueError("date_str must follow the yyyy-mm-dd format.")

    try:
        requested_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError("date_str must follow the yyyy-mm-dd format.") from exc

    if requested_date < datetime.now().date():
        raise ValueError("date_str cannot refer to a past date.")

    def is_booked(room):
        if isinstance(booking_data, pd.DataFrame):
            records = booking_data.to_dict("records")
        elif isinstance(booking_data, dict):
            if room not in booking_data:
                return False
            value = booking_data[room]
            if isinstance(value, dict):
                return bool(value.get(date_str, False))
            if isinstance(value, (list, tuple, set)):
                return date_str in value
            if isinstance(value, str):
                return value in {"Booked", "booked", date_str}
            return bool(value)

        elif isinstance(booking_data, (list, tuple)):
            records = booking_data
        else:
            return False

        for record in records:
            if isinstance(record, dict):
                record_room = record.get("room", record.get("Room"))
                record_date = record.get(
                    "date", record.get("Date", record.get("booking_date"))
                )
                if record_room == room and str(record_date) == date_str:
                    return record.get("status", record.get("Status", "Booked")) != "Available"
            elif isinstance(record, (list, tuple)) and len(record) >= 2:
                if record[0] == room and str(record[1]) == date_str:
                    return True

        return False

    statuses = ["Booked" if is_booked(room) else "Available" for room in ROOMS]
    report = pd.DataFrame({"Room": ROOMS, "Status": statuses})

    _, ax = plt.subplots()
    values = report["Status"].map({"Available": 0, "Booked": 1})
    ax.bar(report["Room"], values)
    ax.set_xlabel("Room")
    ax.set_ylabel("Booking Status")
    ax.set_yticks([0, 1])
    ax.set_yticklabels(["Available", "Booked"])
    ax.set_title(f"Room Booking Status for {date_str}")

    return report, ax

