from sklearn.preprocessing import LabelEncoder


def task_func(df, dct, columns=None):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    result = df.copy()
    result = result.replace(dct)

    categorical_columns = result.select_dtypes(
        include=["object", "category"]
    ).columns

    for column in categorical_columns:
        encoder = LabelEncoder()
        result[column] = encoder.fit_transform(result[column])

    if columns is None:
        numerical_columns = result.select_dtypes(include="number").columns
    else:
        numerical_columns = columns

    for column in numerical_columns:
        mean = result[column].mean()
        std = result[column].std()
        result[column] = (result[column] - mean) / std

    return result

