    return Counter(words).most_common(word_count)

import collections
import matplotlib.pyplot as plt


def task_func(data):
    if not data:
        return None

    scores = collections.defaultdict(list)

    for record in data:
        for student, score in record.items():
            if score is None:
                continue
            if score < 0:
                raise ValueError("Scores cannot be negative")
            scores[student].append(score)

    averages = {
        student: sum(values) / len(values)
        for student, values in scores.items()
        if values
    }

    if not averages:
        return None

    fig, ax = plt.subplots()
    ax.bar(
        list(averages.keys()),
        list(averages.values()),
        color="blue",
    )
    ax.set_title("Average Student Scores")
    ax.set_xlabel("Student")
    ax.set_ylabel("Average Score")
    fig.tight_layout()

    return ax

