import pandas as pd
from scipy.stats import pearsonr


def task_func(data):
    if len(data) < 2:
        return float("nan")

    scores = pd.to_numeric(data["score"], errors="coerce")
    grades = data["grade"]

    valid = scores.notna() & grades.notna()
    scores = scores[valid]
    grades = grades[valid]

    if len(scores) < 2:
        return float("nan")

    encoded_grades = pd.factorize(grades, sort=True)[0]

    return float(pearsonr(scores, encoded_grades)[0])

