import os
import re
import shutil


def task_func(source_directory: str, target_directory: str, pattern: str = r"\d{4}") -> int:
    if not os.path.isdir(source_directory):
        return 0

    try:
        regex = re.compile(pattern)
        os.makedirs(target_directory, exist_ok=True)
    except (OSError, re.error):
        return 0

    moved_count = 0

    for filename in os.listdir(source_directory):
        source_path = os.path.join(source_directory, filename)

        if not os.path.isfile(source_path) or regex.search(filename) is None:
            continue

        try:
            shutil.move(source_path, os.path.join(target_directory, filename))
            moved_count += 1
        except OSError:
            continue

    return moved_count

import time
import threading


def task_func(delay_time: float = 1.0, num_threads: int = 5):
    messages = [None] * num_threads

    def worker(thread_id: int) -> None:
        time.sleep(delay_time)
        messages[thread_id] = f"Delay in thread {thread_id} completed"

    threads = [
        threading.Thread(target=worker, args=(thread_id,))
        for thread_id in range(num_threads)
    ]

    for thread in threads:
        thread.start()

    for thread in threads:
        thread.join()

    return messages

