import re
import os
import glob
from pathlib import Path


def task_func(pattern, directory, extensions):
    regex = re.compile(pattern, re.IGNORECASE)
    directory = os.path.abspath(directory)

    normalized_extensions = []
    for extension in extensions:
        extension = str(extension)
        if extension != "*" and not extension.startswith("."):
            extension = "." + extension
        normalized_extensions.append(extension)

    file_paths = []
    for extension in normalized_extensions:
        pattern_path = os.path.join(directory, "*" if extension == "*" else f"*{extension}")
        file_paths.extend(glob.glob(pattern_path))

    result = []
    for file_path in sorted(set(file_paths)):
        if not os.path.isfile(file_path):
            continue
        try:
            with open(file_path, "r", encoding="utf-8", errors="ignore") as file:
                if regex.search(file.read()):
                    result.append(os.path.abspath(file_path))
        except (OSError, UnicodeError):
            continue

    return result

